"""Pydantic v2 Schema for KAIROS Phase 3 Trading Proposals."""

from datetime import datetime, timezone
from enum import Enum
from typing import Any, List, Optional, Union
from pydantic import BaseModel, Field, field_validator, model_validator


class TradeDirection(str, Enum):
    BUY = "BUY"
    SELL = "SELL"
    HOLD = "HOLD"


class TradingProposal(BaseModel):
    """Institutional Trade Proposal generated by the Phase 3 Trader Agent.
    Strictly simulated; no live execution or broker order routing.
    """

    ticker: str = Field(..., description="NSE Equity Ticker (e.g. RELIANCE)")
    direction: TradeDirection = Field(..., description="Strategic direction: BUY, SELL, or HOLD")
    entry_price: float = Field(..., ge=0.0, description="Recommended entry limit price in INR")
    stop_loss: float = Field(..., ge=0.0, description="Defensive stop-loss boundary in INR")
    target: float = Field(..., ge=0.0, description="Target take-profit objective in INR")
    time_horizon: str = Field(..., description="Recommended trade horizon (e.g., '1-3 MONTHS', '6-12 MONTHS')")
    confidence: float = Field(..., ge=0.0, le=1.0, description="Confidence score between 0.0 and 1.0")
    rationale: str = Field(..., description="Synthesis rationale integrating technicals, fundamentals, and debate")
    data_freshness: str = Field(..., description="Audit status of underlying data freshness and quote delays")
    risk_warnings: List[str] = Field(..., min_length=1, description="Institutional risk caveats and volatility boundaries")

    # Institutional Compliance & Execution Metadata
    risk_reward_ratio: float = Field(default=0.0, ge=0.0, description="Computed from the levels; 0.0 for HOLD (not applicable)")
    levels_reference_only: bool = Field(default=False, description="True for HOLD: entry/stop/target are context levels, not an executable setup")
    level_adjustments: List[str] = Field(default_factory=list, description="Honest record of any level the validator had to repair")
    order_type: str = Field(default="LIMIT", description="Order execution type: LIMIT")
    status: str = Field(default="SIMULATED_PROPOSAL_ONLY", description="Simulation status; strictly not executed")
    disclaimer: str = Field(
        default="KAIROS Phase 3 Simulated Trading Proposal. Strictly advisory & paper research; no live trading or broker execution.",
        description="Non-execution institutional compliance disclaimer",
    )
    execution_mode: str = Field(
        default="DETERMINISTIC_FALLBACK",
        description="'LIVE_GROQ_MODEL' or 'DETERMINISTIC_FALLBACK'",
    )
    generated_at: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())
    risk_preference: str = Field(
        default="NEUTRAL",
        description="User risk preference: CONSERVATIVE, NEUTRAL, or AGGRESSIVE",
    )
    position_sizing: str = Field(
        default="BALANCED (3-5% of portfolio) — Balanced risk and return",
        description="Suggested position sizing allocation based on risk preference",
    )
    preference_influence: str = Field(
        default="Balanced approach: standard technical support buffers and moderate position sizing applied.",
        description="Plain-English explanation of how user risk preference influenced the proposal",
    )
    layman_summary: Optional[dict] = Field(
        default=None,
        description="Plain-English summary for non-technical users explaining action, reasons, levels, risk, and caveats",
    )

    @field_validator("direction", mode="before")
    @classmethod
    def normalize_direction(cls, v: Any) -> Any:
        if isinstance(v, str):
            v_upper = v.strip().upper()
            if v_upper in ("BUY", "LONG", "OVERWEIGHT", "ACCUMULATE"):
                return TradeDirection.BUY
            elif v_upper in ("SELL", "SHORT", "UNDERWEIGHT", "REDUCE"):
                return TradeDirection.SELL
            elif v_upper in ("HOLD", "NEUTRAL"):
                return TradeDirection.HOLD
        return v

    @field_validator("risk_preference", mode="before")
    @classmethod
    def normalize_risk_preference(cls, v: Any) -> str:
        if isinstance(v, str):
            v_upper = v.strip().upper()
            if "CONSERV" in v_upper:
                return "CONSERVATIVE"
            elif "AGGR" in v_upper:
                return "AGGRESSIVE"
            else:
                return "NEUTRAL"
        return "NEUTRAL"

    @field_validator("confidence", mode="before")
    @classmethod
    def normalize_confidence(cls, v: Any) -> float:
        if isinstance(v, str):
            v_upper = v.strip().upper()
            mapping = {
                "STRONG": 0.85,
                "HIGH": 0.85,
                "MODERATE": 0.65,
                "MEDIUM": 0.65,
                "WEAK": 0.40,
                "LOW": 0.40,
            }
            if v_upper in mapping:
                return mapping[v_upper]
            try:
                v = float(v.replace("%", "").strip())
                if v > 1.0 and v <= 100.0:
                    v = v / 100.0
            except ValueError:
                return 0.50
        val = float(v)
        return max(0.0, min(1.0, val))

    @field_validator("risk_reward_ratio", mode="before")
    @classmethod
    def ensure_risk_reward(cls, v: Any, info) -> float:
        if v is not None:
            try:
                val = float(v)
                if val >= 0.0:
                    return round(val, 2)
            except (ValueError, TypeError):
                pass
        return 0.0

    @model_validator(mode="after")
    def validate_and_align_trade_parameters(self) -> "TradingProposal":
        """Checks level direction, records any repair, and computes risk/reward from the levels (never trusts the LLM)."""
        ep = round(float(self.entry_price), 2)
        sl = round(float(self.stop_loss), 2)
        tp = round(float(self.target), 2)
        notes: List[str] = []

        if self.direction == TradeDirection.BUY:  # stop < entry < target
            if sl >= ep:
                notes.append(f"Stop {sl} was not below entry {ep}; replaced with entry -5%.")
                sl = round(ep * 0.95, 2)
            if tp <= ep:
                notes.append(f"Target {tp} was not above entry {ep}; replaced with entry +10%.")
                tp = round(ep * 1.10, 2)
            self.risk_reward_ratio = round((tp - ep) / (ep - sl), 2) if ep > sl else 0.0
        elif self.direction == TradeDirection.SELL:  # target < entry < stop
            if sl <= ep:
                notes.append(f"Stop {sl} was not above entry {ep}; replaced with entry +5%.")
                sl = round(ep * 1.05, 2)
            if tp >= ep:
                notes.append(f"Target {tp} was not below entry {ep}; replaced with entry -10%.")
                tp = round(ep * 0.90, 2)
            self.risk_reward_ratio = round((ep - tp) / (sl - ep), 2) if sl > ep else 0.0
        else:  # HOLD: nothing is executed, so the band is context and has no risk/reward
            if sl >= ep:
                sl = round(ep * 0.95, 2)
            if tp <= ep:
                tp = round(ep * 1.05, 2)
            self.risk_reward_ratio = 0.0
            self.levels_reference_only = True

        self.level_adjustments = [*self.level_adjustments, *notes]
        self.risk_warnings = [*self.risk_warnings, *notes]
        self.entry_price = ep
        self.stop_loss = sl
        self.target = tp
        return self

    def get_layman_summary(
        self,
        analyst_reports: Optional[dict] = None,
        verdict: Optional[Any] = None,
    ) -> dict:
        """Constructs and returns the comprehensive plain-English layman's summary directly from this validated proposal."""
        summary = build_layman_summary(
            ticker=self.ticker,
            direction=self.direction,
            entry_price=self.entry_price,
            stop_loss=self.stop_loss,
            target=self.target,
            time_horizon=self.time_horizon,
            confidence=self.confidence,
            risk_reward_ratio=self.risk_reward_ratio,
            risk_preference=self.risk_preference,
            position_sizing=self.position_sizing,
            preference_influence=self.preference_influence,
            analyst_reports=analyst_reports,
            verdict=verdict,
            rationale=self.rationale,
            risk_warnings=self.risk_warnings,
        )
        self.layman_summary = summary
        return summary


def build_layman_summary(
    ticker: str,
    direction: Union[TradeDirection, str],
    entry_price: float,
    stop_loss: float,
    target: float,
    time_horizon: str,
    confidence: float,
    risk_reward_ratio: float = 0.0,
    risk_preference: str = "NEUTRAL",
    position_sizing: Optional[str] = None,
    preference_influence: Optional[str] = None,
    analyst_reports: Optional[dict] = None,
    verdict: Optional[Any] = None,
    rationale: Optional[str] = None,
    risk_warnings: Optional[List[str]] = None,
) -> dict:
    """Builds an accessible, non-technical plain English summary of a trading proposal.
    Explains action (Buy/Hold/Avoid), 2-3 simple reasons, price levels, risk level,
    time horizon, what could go wrong, risk preference impact, and prominent caveats.
    """
    # 1. Normalize Risk Preference & Influences
    rp_clean = (risk_preference or "NEUTRAL").upper().strip()
    if "CONSERV" in rp_clean:
        user_pref = "Conservative"
        default_pos = "CONSERVATIVE (1-2% of portfolio) — Prioritizing capital protection"
        default_inf = "Prioritizes capital protection: tighter stop-loss limits drawdown risk, entry requires disciplined support pricing, and allocation is capped at 1-2%."
    elif "AGGR" in rp_clean:
        user_pref = "Aggressive"
        default_pos = "AGGRESSIVE (6-8% of portfolio) — Maximizing upside exposure"
        default_inf = "Prioritizes growth potential: wider stop-loss absorbs market noise, target profit objective is extended, and position size is active at 6-8%."
    else:
        user_pref = "Neutral"
        default_pos = "BALANCED (3-5% of portfolio) — Balanced risk and return"
        default_inf = "Balances potential return with risk: standard technical support buffers and moderate 3-5% position size applied."

    pos_size = position_sizing or default_pos
    pref_inf = preference_influence or default_inf

    # 2. Normalize Action
    dir_str = direction.value if hasattr(direction, "value") else str(direction)
    dir_upper = dir_str.upper()

    if dir_upper in ("BUY", "LONG", "OVERWEIGHT", "ACCUMULATE"):
        action = "Buy"
        action_detail = "Consider buying near the recommended entry price."
    elif dir_upper in ("SELL", "SHORT", "UNDERWEIGHT", "REDUCE"):
        action = "Avoid"
        action_detail = "Stay on the sidelines or exit positions to avoid downside risk."
    else:
        action = "Hold"
        action_detail = "Wait and observe; no clear directional edge to buy or sell right now."

    # 2. Extract analyst metrics if available
    reports = analyst_reports or {}
    mkt = reports.get("market", {})
    if hasattr(mkt, "model_dump"):
        mkt = mkt.model_dump()
    fund = reports.get("fundamentals", {})
    if hasattr(fund, "model_dump"):
        fund = fund.model_dump()
    sent = reports.get("sentiment", {})
    if hasattr(sent, "model_dump"):
        sent = sent.model_dump()
    news = reports.get("news", {})
    if hasattr(news, "model_dump"):
        news = news.model_dump()

    support = mkt.get("support_level")
    resistance = mkt.get("resistance_level")
    margin = fund.get("profit_margins")
    solvency = fund.get("solvency_health")
    bull_ratio = sent.get("retail_bull_ratio")
    catalysts = news.get("key_catalysts", [])
    news_risks = news.get("regulatory_and_litigation_risks", [])

    # 3. Generate 2-3 Simple Reasons ("Why?")
    reasons = []
    if rationale and isinstance(rationale, str) and len(rationale.strip()) > 15:
        # Extract full sentences without splitting on decimals like 46.3
        import re
        sentences = [s.strip() for s in re.split(r"(?<=[a-zA-Z])\.\s+", rationale.replace("\n", " ")) if len(s.strip()) > 15]
        for s in sentences[:3]:
            reasons.append(s + ("." if not s.endswith(".") else ""))

    if not reasons:
        if action == "Buy":
            if margin is not None and isinstance(margin, (int, float)) and margin > 0:
                reasons.append(
                    f"Healthy Company Profits: The business generates dependable profits with a healthy {margin * 100:.1f}% net profit margin."
                )
            else:
                reasons.append(
                    "Strong Business Health: The company shows resilient financial health and sustainable core operations."
                )
            if support is not None and isinstance(support, (int, float)) and support > 0:
                reasons.append(
                    f"Price Safety Floor: The stock price is holding firmly above its key safety support level at ₹{float(support):,.2f}."
                )
            else:
                reasons.append(
                    "Attractive Entry Price: The stock is consolidating near an attractive valuation range relative to expected upside."
                )
            if catalysts and len(catalysts) > 0 and isinstance(catalysts[0], str):
                clean_cat = catalysts[0].strip()
                reasons.append(f"Upcoming Growth Driver: Positive momentum supported by '{clean_cat}'.")
            else:
                reasons.append(
                    "Positive Research Consensus: Multi-agent research confirms favorable upside potential outweighs downside risk."
                )
        elif action == "Avoid":
            reasons.append(
                "Stretched Valuation: The current stock price looks high compared to underlying earnings and cash flow."
            )
            if resistance is not None and isinstance(resistance, (int, float)) and resistance > 0:
                reasons.append(
                    f"Selling Ceiling: The stock faces strong selling resistance near ₹{float(resistance):,.2f} and struggles to climb."
                )
            else:
                reasons.append(
                    "Downward Price Pressure: Technical indicators suggest price momentum is fading."
                )
            reasons.append(
                "Unfavorable Risk vs. Reward: Downside risk is greater than potential gain; capital preservation is the top priority."
            )
        else:  # Hold
            if support and resistance and isinstance(support, (int, float)) and isinstance(resistance, (int, float)):
                reasons.append(
                    f"Moving Sideways: The stock is trading in a neutral band between ₹{float(support):,.2f} and ₹{float(resistance):,.2f}."
                )
            else:
                reasons.append(
                    "Moving Sideways: The stock lacks a strong upward or downward trend at this moment."
                )
            reasons.append(
                "Mixed Signals: Positive business factors are balanced out by broader market and sector caution."
            )
            reasons.append(
                "Better to Wait: Waiting for a clear breakout or discount avoids unnecessary risk."
            )

    # Ensure 2-3 reasons
    reasons = reasons[:3]

    # 4. Entry Price Explanation
    entry_price_str = f"Around ₹{entry_price:,.2f}"
    if action == "Buy":
        entry_explanation = "The price level where buying becomes attractive."
    elif action == "Avoid":
        entry_explanation = "Current reference price; buying is NOT advised."
    else:
        entry_explanation = "Current price; observe price action before considering an entry."

    # 5. Stop-Loss Explanation
    stop_loss_str = f"₹{stop_loss:,.2f}"
    stop_loss_explanation = "The safety boundary where losses should be limited. If the price drops below this level, exit immediately to protect your money."

    # 6. Target Price Explanation
    target_str = f"₹{target:,.2f}"
    target_explanation = "The potential selling price to take profit if the positive scenario plays out."

    # 7. Risk Level & Explanation
    if action == "Buy":
        if user_pref == "Conservative":
            risk_level = "Low-Medium"
            risk_explanation = "Capital preservation prioritized: tightened stop-loss limits downside exposure."
        elif user_pref == "Aggressive":
            risk_level = "High"
            risk_explanation = "Aggressive growth setup: wider stop-loss tolerance accepted to capture larger breakout profits."
        else:
            if confidence >= 0.75 and risk_reward_ratio >= 1.5:
                risk_level = "Medium"
                risk_explanation = "The company has solid financial footing, but all stock investments carry market fluctuations."
            else:
                risk_level = "High"
                risk_explanation = "Moderate analyst confidence or higher price volatility means a higher chance of short-term pullbacks."
    elif action == "Avoid":
        risk_level = "High"
        risk_explanation = "Elevated valuation or downward momentum increases downside risk; capital preservation is priority."
    else:  # Hold
        risk_level = "Low-Medium" if user_pref == "Conservative" else "Medium"
        risk_explanation = "The stock is neutral and moving sideways; risk is contained while waiting for a confirmed breakout."

    # 8. Time Horizon Explanation
    th_upper = str(time_horizon).upper()
    if "3-6" in th_upper:
        time_horizon_plain = "3 to 6 months (Medium-term investment)"
    elif "1-3" in th_upper:
        time_horizon_plain = "1 to 3 months (Short-term idea)"
    elif "6-12" in th_upper or "1 YEAR" in th_upper:
        time_horizon_plain = "6 to 12 months (Long-term investment)"
    elif "WEEK" in th_upper or "MONITOR" in th_upper:
        time_horizon_plain = "1 to 4 weeks (Wait and watch)"
    else:
        time_horizon_plain = f"{time_horizon} (Expected duration for this idea)"

    # 9. What could go wrong? (Key risks in plain language)
    what_could_go_wrong = []
    if risk_warnings and isinstance(risk_warnings, list):
        for w in risk_warnings:
            w_str = str(w).strip()
            # Filter out non-execution legal boilerplate from plain-English briefing
            if any(term in w_str.upper() for term in ["NON-EXECUTION", "STRICTLY SIMULATED", "PAPER PROPOSAL"]):
                continue
            if len(w_str) > 10:
                what_could_go_wrong.append(w_str)
            if len(what_could_go_wrong) >= 3:
                break

    if not what_could_go_wrong:
        what_could_go_wrong = [
            "Overall Market Drop: If broader Indian stock markets (e.g., Nifty) drop, this stock is likely to fall too.",
            f"Price Falling Below Stop-Loss: If the stock drops below ₹{stop_loss:,.2f}, the positive thesis is broken and losses must be cut.",
            "Economic & Sector Headwinds: Unexpected changes in interest rates, government policy, or slowing customer demand.",
        ]
    what_could_go_wrong = what_could_go_wrong[:3]

    # 10. Compliance Disclaimer
    disclaimer = (
        "⚠️ IMPORTANT NOTICE: Strictly educational and simulated research. "
        "NO real trade has been executed. Profits are NEVER guaranteed, and investing carries financial risk. "
        "Always do your own research before making investment decisions."
    )

    return {
        "action": action,
        "action_detail": action_detail,
        "reasons": reasons,
        "entry_price": entry_price_str,
        "entry_explanation": entry_explanation,
        "stop_loss": stop_loss_str,
        "stop_loss_explanation": stop_loss_explanation,
        "target_price": target_str,
        "target_explanation": target_explanation,
        "risk_level": risk_level,
        "risk_explanation": risk_explanation,
        "time_horizon": time_horizon_plain,
        "what_could_go_wrong": what_could_go_wrong,
        "user_risk_preference": user_pref,
        "position_sizing": pos_size,
        "preference_influence": pref_inf,
        "disclaimer": disclaimer,
    }


def format_layman_summary_terminal(
    proposal: Union[TradingProposal, dict],
    analyst_reports: Optional[dict] = None,
    verdict: Optional[Any] = None,
) -> str:
    """Formats the layman's summary into a clean, readable terminal card."""
    if isinstance(proposal, TradingProposal):
        ticker = proposal.ticker
        summary = proposal.get_layman_summary(analyst_reports=analyst_reports, verdict=verdict)
    elif isinstance(proposal, dict):
        ticker = proposal.get("ticker", "UNKNOWN")
        summary = build_layman_summary(
            ticker=ticker,
            direction=proposal.get("direction", "HOLD"),
            entry_price=float(proposal.get("entry_price", 0.0)),
            stop_loss=float(proposal.get("stop_loss", 0.0)),
            target=float(proposal.get("target", 0.0)),
            time_horizon=str(proposal.get("time_horizon", "3-6 MONTHS")),
            confidence=float(proposal.get("confidence", 0.5)),
            risk_reward_ratio=float(proposal.get("risk_reward_ratio", 0.0)),
            risk_preference=proposal.get("risk_preference", "NEUTRAL"),
            position_sizing=proposal.get("position_sizing"),
            preference_influence=proposal.get("preference_influence"),
            analyst_reports=analyst_reports,
            verdict=verdict,
            rationale=proposal.get("rationale"),
            risk_warnings=proposal.get("risk_warnings"),
        )
    else:
        return ""

    action = summary.get("action", "Hold")
    action_detail = summary.get("action_detail", "")
    reasons = summary.get("reasons", [])
    entry_price = summary.get("entry_price", "N/A")
    entry_explanation = summary.get("entry_explanation", "")
    stop_loss = summary.get("stop_loss", "N/A")
    stop_loss_explanation = summary.get("stop_loss_explanation", "")
    target_price = summary.get("target_price", "N/A")
    target_explanation = summary.get("target_explanation", "")
    risk_level = summary.get("risk_level", "Medium")
    risk_explanation = summary.get("risk_explanation", "")
    time_horizon = summary.get("time_horizon", "N/A")
    what_could_go_wrong = summary.get("what_could_go_wrong", [])
    user_risk_preference = summary.get("user_risk_preference", "Neutral")
    position_sizing = summary.get("position_sizing", "Moderate (3-5% of portfolio)")
    preference_influence = summary.get("preference_influence", "")

    lines = [
        "\n" + "=" * 80,
        f"  KAIROS INVESTOR BRIEFING (Plain English Summary): {ticker}",
        "=" * 80,
        f"  • What should I do?    {action.upper()} — {action_detail}",
        "",
        "  • Why? (Key Research Reasons):",
    ]
    for idx, r in enumerate(reasons, 1):
        lines.append(f"      {idx}. {r}")

    lines.extend([
        "",
        f"  • Entry price:         {entry_price} ({entry_explanation})",
        f"  • Stop-loss:           {stop_loss} ({stop_loss_explanation})",
        f"  • Target price:        {target_price} ({target_explanation})",
        f"  • Risk level:          {risk_level.upper()} — {risk_explanation}",
        f"  • Risk Preference:     {user_risk_preference.upper()}",
        f"  • Strategy Impact:     {preference_influence}",
        f"  • Suggested Allocation:{position_sizing}",
        f"  • Time horizon:        {time_horizon}",
        "",
        "  • What could go wrong? (Key Risks in Plain Language):",
    ])
    for w in what_could_go_wrong:
        lines.append(f"      • {w}")

    lines.extend([
        "",
        "  ⚠️  IMPORTANT NOTICE (Simulated Research Only):",
        "      • This is an automated educational simulation, NOT financial advice.",
        "      • Profits are NEVER guaranteed, and capital is always at risk in stock markets.",
        "      • NO real trade has been placed (strictly paper/simulated proposal).",
        "=" * 80,
    ])
    return "\n".join(lines)


def print_layman_summary(
    proposal: Union[TradingProposal, dict],
    analyst_reports: Optional[dict] = None,
    verdict: Optional[Any] = None,
) -> None:
    """Prints the readable plain-English layman's summary to stdout."""
    card = format_layman_summary_terminal(proposal, analyst_reports=analyst_reports, verdict=verdict)
    if card:
        print(card, flush=True)


